from core import *

def pp(x):return f'{100*x:.2f}pp'
def pct(x):return f'{100*x:.2f}%'
def main():
    r=read(HERE/'results.json');f=read(HERE/'PROBE_SELECTION_FREEZE.json');v=read(HERE/'VALIDITY_GATE.json');gate=read(HERE/'VIDEO_GATE.json');post=read(HERE/'main_POSTFLIGHT.json');a=r['active_variants'];d1=r['D1'];d2=r['D2'];d3=r['D3']
    lines=[f"# Round20：跨场景无标签探测选择（{utc()}）",'',f"新几何变体上，预注册的无标签前期探测加两个时间表的规则 **D1 {d1['status']}**（平均/最大遗憾 {pp(d1['mean'])}/{pp(d1['max'])}），相对开发集源均值臂 S15→10@5H/7 的改进 **D2 {d2['status']}**（平均遗憾差 {pp(d2['mean_regret_difference'])}，95% CI [{pp(d2['ci'][0])}, {pp(d2['ci'][1])}]）；两个时间表菜单 **D3 {d3['status']}**（≤3pp 的变体 {d3['within_3pp']}/{d3['total']}）。Ring 两个新半径变体均未通过独立 pilot 有效性门，结论只覆盖 Toy 和 DB 的六个有效宽度变体。",'', '## 事实：门与冻结','',f"- 原几何 8/8 逐位一致：终止事件、长度、首动作 float64 字节。证据见 `CONSISTENCY_GATE.json`。",f"- 新初态 640 个，物理与数据库去重通过；几何放置及通道容量检查通过。",f"- pilot 256 条；probe 384 条，1 条 Ring_075 数值 unknown（该变体随后因 pilot 无效被排除），不重跑。probe 无成功/终止字段。",f"- 预注册 SHA256 `{sha(HERE/'PREREGISTRATION.md')}`，规则冻结 SHA256 `{sha(HERE/'PROBE_SELECTION_FREEZE.json')}`；两者都早于首个评估标签。",f"- 主评估 {post['planned']} 条，unknown {post['unknown']}，raw/trace/DB postflight `{post['status']}`。",'', '| 变体 | pilot F10/F15 | stall13 / stall15 | 选择 | 七臂最佳 | 规则遗憾 | 菜单遗憾 |','| --- | --- | --- | --- | --- | ---: | ---: |']
    for variant in sorted(v['variants']):
        q=v['variants'][variant];fe=f['features'].get(variant);sel=f['selections'].get(variant,'—');row=r['oracle'].get(variant);lines.append(f"| {variant} | {pct(q['rates']['F10'])} / {pct(q['rates']['F15'])} | {pp(fe['13']['stall'])+' / '+pp(fe['15']['stall']) if fe else 'excluded'} | {sel} | {row['arm'] if row else 'excluded'} | {pp(r['regret'][variant]) if row else '—'} | {pp(r['menu_regret'][variant]) if row else '—'} |")
    lines+=['','**流程偏差：** pilot 与 probe 曾并发提交，故两个随后被有效性门排除的 Ring 变体也产生了 64 条额外无标签 probe。它们不进入冻结特征、规则选择或 D1–D3；没有新成功标签因此偏差不能影响评估选择，但违反“仅对有效变体探测”的执行顺序。主评估的官方 preflight 文件在提交前生成，额外的哈希收据在提交后才写入；`FREEZE_TIMELINE_AUDIT.json` 核对预注册、选择冻结、官方 preflight 均早于第一条评估 raw，且如实标注收据的较晚时间。','', 'probe 的另外两项冻结描述统计：','', '| 变体 | progress13 / progress15 | 最小两两距离13 / 15 (m) |','| --- | --- | --- |']
    for variant,fe in sorted(f['features'].items()):lines.append(f"| {variant} | {pct(fe['13']['progress'])} / {pct(fe['15']['progress'])} | {fe['13']['minimum_pair_distance']:.4f} / {fe['15']['minimum_pair_distance']:.4f} |")
    lines+=['','## 七臂成功率','', '| 变体 | F10 | F13 | F15 | S13@t1 | S13@t2 | S15@t1 | S15@t2 |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
    for variant in a:lines.append('| '+variant+' | '+' | '.join(pct(r['rates'][variant][arm]) for arm in ARMS)+' |')
    lines+=['','## 终点与不确定性','',f"D1 平均/最大遗憾的 state 成簇 95% CI 分别为 [{pp(d1['mean_ci'][0])}, {pp(d1['mean_ci'][1])}] / [{pp(d1['max_ci'][0])}, {pp(d1['max_ci'][1])}]；unknown 下/上界分别为 [{pp(d1['unknown_mean_bounds'][0])}, {pp(d1['unknown_mean_bounds'][1])}] / [{pp(d1['unknown_max_bounds'][0])}, {pp(d1['unknown_max_bounds'][1])}]。",f"D2 是 R 遗憾减源臂遗憾，越小越好；unknown 边界 [{pp(d2['unknown_bounds'][0])}, {pp(d2['unknown_bounds'][1])}]。Bootstrap 5000 次，按 state 成簇、七臂与 seed 配对。",f"D3 为逐变体菜单较优臂距七臂 oracle ≤3pp 的比例；没有额外比例显著性阈值。",'', 'D4 原几何仅 DEVELOPMENT：Toy 选 S13@t1，与 round13 事后最佳一致；DB 选 S13@t1，与其 F15 最佳不一致；Four、Ring 选 S15@t2，分别近于最佳固定 F15、但偏离 Ring 的 S15@t1 最佳。原几何不参与 D1–D3。','', 'round13 设计者事后表已用逐臂原始计数复核（`ROUND13_DEVELOPMENT_RECHECK.json`）：Toy S13@t1 75.208%、S15@t2 61.042%；DB 26.042%/98.750%；Four 98.958%/99.583%；Ring 95.417%/94.375%。对应 oracle 分别为 S13@t1、F15、F15、S15@t1。','', '## 失败类型与发生时间','']
    for variant in a:
        lines.append(f'### {variant}\n')
        for arm in ARMS:
            z=r['failure_summary'].get(variant,{}).get(arm,{});lines.append(f"- {arm}: {z.get('counts',{})}，步数 {z.get('earliest','—')}–{z.get('latest','—')}。")
        lines.append('')
    lines+=['## 解释与边界','', '前期停滞规则是否可迁移由 D1/D2 的新变体数据决定。probe 关闭成功终止，因而到达目标后保持静止的机器人也可贡献 stall；这可能使强 η 的高进展与高停滞同时出现。此为从特征定义和观测作出的解释，不是另一次确认试验，也不改变冻结规则。Ring 新变体两个固定臂都 0/16，不能把它们的失败算成选择器失败或成功。结论不延伸到新拓扑。','', '## 视频与交付','',f"统一入口状态 `{gate['status']}`，完整视频数 {len(read(HERE/'videos/manifest.json')['videos'])}；缺失角色 `{gate['missing_roles']}`。Toy、DB 各三个完整真实视频，两组不同初态的死锁基线/成功干预通过 `VIDEO_PAIR_AUDIT.json` 核对同 seed、几何、初态与连续运动安全余量。Ring 无原生死锁判据，Four 本轮无前瞻评估；历史原几何安全视频仅作明确标注的缓存参照，不填正式死锁角色。timeout 始终保留为 timeout。缺视频时 batch 状态为 `NUMERICAL_COMPLETE_VIDEO_INCOMPLETE`，launcher 非零退出。",'', '全部新文件仅在本目录。未改核心组件，未修改或删除历史资产，未做 git commit。']
    (HERE/'REPORT.md').write_text('\n'.join(lines)+'\n')
    handoff=['# Round20 handoff','',f"状态：D1 {d1['status']}；D2 {d2['status']}；D3 {d3['status']}；数值 postflight {post['status']}；视频 gate {gate['status']}。",'', '权威要求：`docs/prompt_round20_cross_scene_probe_selection_20261014.md` 与仓库 `AGENTS.md`。','', '本目录关键文件：`PREREGISTRATION.md` 及 `.receipt.json`；`CONSISTENCY_GATE.json`；`GEOMETRIES.json`、`FRESH_STATES.json`、`STATE_DEDUP_AUDIT.json`；`pilot_*`、`probe_*`、`main_*` preflight/postflight；`VALIDITY_GATE.json`；`PROBE_SELECTION_FREEZE.json` 及收据；`results.json`；两张 PNG；`videos/manifest.json`；`REPORT.md`。','', 'runtime 继承 E8 FF 与 round13 η schedule。pilot 两个 Ring 半径变体均排除；主评估为 Toy/DB 6 变体 × 3 算子 × 40 state × 7 臂 × 2 seed。所有目标 episode 完整 raw/trace 已进入共享 DB；unknown 不重跑。probe 为无标签部分轨迹，DB 模式没有成功字段可供合并，保留独立 preflight、12 个本地无标签 journal（`probe_JOURNAL_INDEX.json`）及 postflight。pilot/probe 并发造成额外 64 条无标签 Ring probe，已排除，不参与冻结选择。', '', '视频缺口由 `VIDEO_GATE.json` 逐角色记录，统一入口非零，不能宣布完整 batch。继续研究时优先检验更能区分目标到达静止与堵塞的预注册探测，但本轮禁止事后替换规则。']
    (HERE/'HANDOFF.md').write_text('\n'.join(handoff)+'\n')
    print('Wrote REPORT.md and HANDOFF.md')
if __name__=='__main__':main()
